// High School course unit (docs/design/COURSES.md, docs/design/COURSE_QUALITY.md): AP English Literature and Composition,
// Unit 3, Longer Fiction or Drama I. Our own wording and questions, written to the public outline of the AP English Literature
// and Composition Course and Exam Description: its Big Ideas as they apply to the third unit, Character (CHR), Setting (SET),
// Structure (STR), Narration (NAR) and Literary Argumentation (LAN). The outline entries below are named by those Big Idea
// abbreviations; the course's numbered topics and skill codes are not cited because they were not checked against the current
// document, and which Big Idea a given skill falls under here is our own grouping. Six skills. Longer works are taught through
// plot-level facts about Hamlet, Julius Caesar, A Midsummer Night's Dream, A Doll's House, The Importance of Being Earnest,
// Ethan Frome, The Great Gatsby, Frankenstein and Jane Eyre, plus short passages labelled "Fictional passage" or "Fictional
// scene" written for this unit. Every real line quoted is short, public domain (published before 1930) and named with author,
// work and date; Shakespeare is in modernized spelling and punctuation, which differs between editions. Nothing from A Doll's
// House is quoted: its plot is paraphrased, and William Archer's English translation (1889) is the public-domain text a reader
// would use. None of the passages used by English 9, English 10, AP Lang, AP Lit Unit 1 or Unit 2 is reused. Readings of
// symbols are hedged as common readings. Every question offers lettered choices in its prompt and takes the letter (or the
// choice's own words); the right letter moves around.
const tab=(title,rows,cols=['Value'])=>({t:'setups',title,head:'',rows,cols});
/* Video pictures: figure coordinates use a 100 x 34 sketch, north/up. Flow arrows trace before labels appear. */
const sketch=(title,regions,notes=[])=>{const pts={},polys=[];regions.forEach(([label,xy,col=0],i)=>{const v=xy.map(([x,y],k)=>{const n=String.fromCharCode(65+k)+i;pts[n]=[x,y];return n;}).join('');polys.push({v,label,col});});return {t:'figure',title,view:[0,100,0,34],pts,polys,notes:notes.map(([x,y,text])=>({at:[x,y],text})),dots:'',hide:Object.keys(pts).join('')};};
const flow=(title,stages)=>{const q=sketch(title,stages.map(([label],i)=>[label,[[i*36,13],[i*36+28,13],[i*36+28,25],[i*36,25]],i]),stages.map(([,detail],i)=>[i*36+14,7,detail]));q.segs=[];for(let i=0;i<2;i++){q.pts['P'+i]=[i*36+29,19];q.pts['Q'+i]=[i*36+35,19];q.segs.push({v:`P${i}Q${i}`,arrows:1,col:i,w:2});}q.hide=Object.keys(q.pts).join('');return q;};
const arc=(title,xy,notes)=>{const pts={},segs=[];xy.forEach((p,i)=>{pts['P'+i]=p;if(i)segs.push({v:`P${i-1}P${i}`,col:i<4?0:1,w:3});});return {t:'figure',title,view:[0,100,0,34],pts,segs,notes:notes.map(([x,y,text])=>({at:[x,y],text})),dots:'',hide:Object.keys(pts).join('')};};
const board=(title,lines,why)=>({t:'board',title,lines,...(why?{why}:{})});
const pass=(title,texts,small=true)=>({t:'passages',title,texts,...(small?{small:true}:{})});
const L='ABCDEF';
const dot=o=>o.replace(/\.$/,'');
const choose=(right,wrong,k)=>{right=dot(right);const opts=wrong.map(dot);opts.splice(k%(wrong.length+1),0,right);return {text:opts.map((o,i)=>`${L[i]}: ${o}`).join(', '),letter:L[opts.indexOf(right)],n:opts.length};};
const ask=n=>n===2?'Answer A or B.':n===3?'Answer A, B or C.':`Answer ${[...L.slice(0,n-1)].join(', ')} or ${L[n-1]}.`;
